import logging
from bank_connector.app.processors.base import BaseProcessor
from bank_connector.app.processors.stripe_processor import StripeProcessor
from bank_connector.app.schemas.connector import AuthorizeRequest

logger = logging.getLogger(__name__)


class ProcessorRouter:
    """
    Routes payments to the correct processor.

    Current: All → Stripe
    Future:
        Visa high-value  → Direct acquiring bank
        International    → Adyen
        India            → Razorpay
        Backup           → Stripe (if primary down)
    """

    def __init__(self):
        self.processors: dict[str, BaseProcessor] = {
            "stripe": StripeProcessor(),
        }
        self.default = "stripe"

    def get_processor(self, request: AuthorizeRequest) -> BaseProcessor:
        """
        Routing logic - currently always Stripe.
        Expand this logic when adding more processors.
        """
        processor_name = self._route(request)
        processor = self.processors.get(processor_name)

        if not processor:
            logger.warning(f"Processor {processor_name} not found, using default")
            processor = self.processors[self.default]

        logger.info(
            f"Routing payment={request.payment_id} "
            f"amount={request.amount} → {processor.name}"
        )
        return processor

    def _route(self, request: AuthorizeRequest) -> str:
        """
        Routing rules.
        All go to Stripe for now.
        Add rules here as you expand.
        """
        # Future routing logic:
        # if request.amount > 1_000_000:  # > $10,000
        #     return "adyen"
        # if card_country == "IN":
        #     return "razorpay"
        return "stripe"

    def get_by_name(self, name: str) -> BaseProcessor | None:
        return self.processors.get(name)

    def all_processors(self) -> list[BaseProcessor]:
        return list(self.processors.values())
